/**
 * seed-books.js — the collection the library opens with.
 *
 * This file does almost nothing on its own. It joins four sources:
 *
 *   catalogue.js            the books, with descriptions and genres
 *   covers.js               verified real cover images, keyed by title
 *   corrections.js          the cleaning pipeline (split, spell, dedupe)
 *   birthday-candidates.js  books that are NOT hers — see below
 *
 * Keeping them apart means the catalogue can be edited by a human, the
 * covers can be regenerated by a script, and the cleaning rules can be
 * reused by the importer — all without any of them knowing about the
 * others.
 *
 * NOTHING here sets a reading status. Every book arrives on the to-read
 * pile because guessing what she has already read would be inventing
 * facts about her.
 */

import { CATALOGUE, CATALOGUE_VERSION } from './catalogue.js';
import { coverMetaFor } from './covers.js';
import { cleanRows } from './corrections.js';
import { BIRTHDAY_CANDIDATES } from './birthday-candidates.js';
import { bookKey } from '../utils/text.js';

export const SEED_VERSION = CATALOGUE_VERSION;

/**
 * The seed list, in the shape makeBook() expects.
 *
 * Runs through the same cleaning pipeline as a pasted spreadsheet, so a
 * mistake typed into catalogue.js is caught exactly like one typed into
 * the import box.
 *
 * The cover is attached as METADATA — url plus where it came from — not
 * baked into any component. A book with no verified cover gets no URL at
 * all and falls back to its generated one, which is the honest answer
 * and the list Phase 2 works through.
 */
export const SEED_BOOKS = cleanRows(CATALOGUE).map((book) => {
  const cover = coverMetaFor(book.title);
  return {
    ...book,
    coverUrl: cover?.url ?? '',
    coverRef: cover?.coverRef ?? '',
    coverSource: cover?.source ?? '',
  };
});

/**
 * Books that used to be seeded and have since been pulled out of the
 * catalogue on purpose.
 *
 * A seed top-up will remove these from an existing library, but only
 * while they are untouched — no status, rating, notes or tags. Anything
 * she has actually engaged with stays, because a catalogue edit does not
 * get to delete her reading.
 *
 * Klara and the Sun is here because it is a present, not one of her
 * books. It lives in birthday-candidates.js now.
 */
export const RETIRED_KEYS = BIRTHDAY_CANDIDATES.map((b) => bookKey(b.title, b.author));

/** What the shelves actually hold, for anything that wants to say a number. */
export const SEED_COUNT = SEED_BOOKS.length;

export default SEED_BOOKS;
